# ONE FILE - build + publish on SERVER from 921 (Mac repacks do NOT publish on this box).
# Copy ONLY this file to C:\Users\Administrator\Desktop\Erp\
# Requires: at least one Felix .app in same folder (908, 907, 904, etc.). 921 preferred if present.
# Run Business Central Administration Shell AS ADMINISTRATOR:
#   cd $env:USERPROFILE\Desktop\Erp
#   Set-ExecutionPolicy -Scope Process Bypass -Force
#   .\Install-AbhBc928.ps1

$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.IO.Compression

$ErpFolder = "$env:USERPROFILE\Desktop\Erp"
$ServerInstance = "BC240"
$TargetVersion = "1.0.2.928"
$AppName = "BC24_TA App"
$Publisher = "Technology Associates EA Ltd"
$TargetAl = "src/src/src/src/src/src/src/src/src/src/NEWCHANGES/StaffPortalCodeunit.Codeunit.al"

Set-Location $ErpFolder

$base921 = Join-Path $ErpFolder "Technology Associates EA Ltd_BC24_TA App_1.0.2.921.app"
if (-not (Test-Path $base921)) {
  $candidates = Get-ChildItem -Path $ErpFolder -Filter "Technology Associates EA Ltd_BC24_TA App_*.app" |
    Where-Object { $_.Name -notmatch '\.927\.|\.925\.|\.928\.' } |
    Sort-Object { try { [version]($_.BaseName -replace '.*_(\d+\.\d+\.\d+\.\d+)$', '$1') } catch { [version]"0.0.0.0" } } -Descending
  if (-not $candidates) { throw "Need a Felix .app in Erp folder (e.g. 908.app). Mac 925/927 repacks cannot publish here." }
  $base921 = $candidates[0].FullName
  Write-Host "Using base: $($candidates[0].Name)" -ForegroundColor Yellow
}

$alB64 = @"

"@

$newAl = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($alB64.Trim()))
if ($newAl -notmatch "action = 'delete'") { throw "Embedded AL missing leave cancel" }

$outPath = Join-Path $ErpFolder ("Technology Associates EA Ltd_BC24_TA App_{0}.app" -f $TargetVersion)
Write-Host "Building $TargetVersion on server from $(Split-Path $base921 -Leaf)..." -ForegroundColor Cyan

$bytes = [IO.File]::ReadAllBytes($base921)
if ([Text.Encoding]::ASCII.GetString($bytes, 0, 4) -ne "NAVX") { throw "921.app is not NAVX" }
$header = $bytes[0..39]
$zipBytes = $bytes[40..($bytes.Length - 1)]

$inMs = New-Object IO.MemoryStream(,$zipBytes)
$outMs = New-Object IO.MemoryStream
$inZip = New-Object IO.Compression.ZipArchive($inMs, [IO.Compression.ZipArchiveMode]::Read)
$outZip = New-Object IO.Compression.ZipArchive($outMs, [IO.Compression.ZipArchiveMode]::Create, $true)

$replaced = $false
foreach ($entry in $inZip.Entries) {
    $name = if ($entry.FullName -eq "perm/file1_%5BContent_Types%5D.xml") { "perm/file1_[Content_Types].xml" } else { $entry.FullName }
    $outEntry = $outZip.CreateEntry($name, [IO.Compression.CompressionLevel]::Optimal)
    $src = $entry.Open()
    $dst = $outEntry.Open()
    if ($name -eq $TargetAl) {
        $replaced = $true
        $writer = New-Object IO.StreamWriter($dst)
        $writer.Write($newAl)
        $writer.Close()
    } elseif ($name -eq "NavxManifest.xml") {
        $reader = New-Object IO.StreamReader($src)
        $xml = $reader.ReadToEnd()
        $reader.Close()
        $xml = [regex]::Replace($xml, 'Version="1\.0\.2\.\d+"', "Version=`"$TargetVersion`"", 1)
        $writer = New-Object IO.StreamWriter($dst)
        $writer.Write($xml)
        $writer.Close()
    } else {
        $src.CopyTo($dst)
    }
    $dst.Close(); $src.Close()
}
$inZip.Dispose(); $outZip.Dispose(); $inMs.Dispose()
if (-not $replaced) { throw "StaffPortal AL not found inside 921.app" }

$newZip = $outMs.ToArray(); $outMs.Dispose()
$newSize = [BitConverter]::GetBytes([int64]$newZip.Length)
for ($i = 0; $i -lt 8; $i++) { $header[28 + $i] = $newSize[$i] }
$final = New-Object byte[] ($header.Length + $newZip.Length)
[Array]::Copy($header, 0, $final, 0, $header.Length)
[Array]::Copy($newZip, 0, $final, $header.Length, $newZip.Length)
[IO.File]::WriteAllBytes($outPath, $final)
Write-Host "Built: $outPath ($($final.Length) bytes)" -ForegroundColor Green

Write-Host "Publishing..." -ForegroundColor Yellow
Publish-NAVApp -Path $outPath -ServerInstance $ServerInstance -SkipVerification

$pub = Get-NAVAppInfo -ServerInstance $ServerInstance -Name $AppName -Publisher $Publisher |
    Where-Object { $_.Version -eq [version]$TargetVersion -and $_.IsPublished }
if (-not $pub) {
    throw "Publish failed. Mac/copied repacks do not work on this server — this build was made locally from 921. Check Application event log."
}
Write-Host "Published $TargetVersion" -ForegroundColor Green

Sync-NAVApp -ServerInstance $ServerInstance -Tenant default -Name $AppName -Publisher $Publisher -Version $TargetVersion
Start-NAVAppDataUpgrade -ServerInstance $ServerInstance -Tenant default -Name $AppName -Publisher $Publisher -Version $TargetVersion

Get-NAVAppInfo -ServerInstance $ServerInstance -Tenant default -TenantSpecificProperties -Name $AppName |
    Where-Object { $_.Version -eq [version]$TargetVersion } |
    Format-List Name, Version, IsPublished, IsInstalled
Write-Host "Republish CuStaffPortal 50049 in Web Services." -ForegroundColor Green
